import '../models/colaborador_model.dart';
import '../models/loja_model.dart';
import '../models/produto_model.dart';
import '../models/loja_produto_model.dart';
import 'local/local_data_source.dart';

/// Seed data for initial population of the database
class SeedData {
  static const int versionSeed = 1;

  /// Seed the database.
  ///
  /// Manually maps products to stores per user using the internal
  /// `manualLojaProdutos*` maps defined below. This seed no longer performs
  /// automatic linking; edit the manual maps to control which products are
  /// assigned to which store for each collaborator.
  static Future<void> seedInitialData(LocalDataSource dataSource) async {
    try {
      // Create users (colaboradores)
      final daniel = ColaboradorModel(
        nome: 'Daniel',
        email: 'daniel@email.com',
        login: 'daniel@email.com',
        senha: 'senha123',
        dataCadastro: DateTime.now(),
      );

      final vinicius = ColaboradorModel(
        nome: 'Vinícius',
        email: 'vinicius@email.com',
        login: 'vinicius@email.com',
        senha: 'senha123',
        dataCadastro: DateTime.now(),
      );

      final ricardo = ColaboradorModel(
        nome: 'Ricardo',
        email: 'ricardo@email.com',
        login: 'ricardo@email.com',
        senha: 'senha123',
        dataCadastro: DateTime.now(),
      );

      // Insert users and get their IDs
      final idDaniel = await dataSource.inserirColaborador(daniel);
      final idVinicius = await dataSource.inserirColaborador(vinicius);
      final idRicardo = await dataSource.inserirColaborador(ricardo);

      // Create stores for Daniel (3 stores in São Paulo)
      final lojasDaniel = <LojaModel>[
        LojaModel(
          nome: 'Mercado Central SP',
          endereco: 'Rua A, 100',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idDaniel,
          tempoMedioColeta: 300,
        ),
        LojaModel(
          nome: 'Super Vale SP',
          endereco: 'Av B, 200',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idDaniel,
          tempoMedioColeta: 300,
        ),
        LojaModel(
          nome: 'Atacado São Paulo',
          endereco: 'Rua C, 300',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idDaniel,
          tempoMedioColeta: 300,
        ),
      ];

      // Create stores for Vinicius (3 stores in São Paulo)
      final lojasVinicius = <LojaModel>[
        LojaModel(
          nome: 'Mercado Norte SP',
          endereco: 'Rua D, 400',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idVinicius,
          tempoMedioColeta: 300,
        ),
        LojaModel(
          nome: 'Super Sul SP',
          endereco: 'Av E, 500',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idVinicius,
          tempoMedioColeta: 300,
        ),
        LojaModel(
          nome: 'Atacado Central',
          endereco: 'Rua F, 600',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idVinicius,
          tempoMedioColeta: 300,
        ),
      ];

      final lojasRicardo = <LojaModel>[
        LojaModel(
          nome: 'Mercado Sul SP',
          endereco: 'Rua D, 400',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idRicardo,
          tempoMedioColeta: 300,
        ),
        LojaModel(
          nome: 'Super Norte SP',
          endereco: 'Av E, 500',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idRicardo,
          tempoMedioColeta: 300,
        ),
        LojaModel(
          nome: 'Atacado do Vale',
          endereco: 'Rua F, 600',
          cidade: 'São Paulo',
          estado: 'SP',
          idColaborador: idRicardo,
          tempoMedioColeta: 300,
        ),
      ];


      // Insert stores
      await dataSource.upsertLojas(lojasDaniel);
      await dataSource.upsertLojas(lojasVinicius);
      await dataSource.upsertLojas(lojasRicardo);

      // Create products for Daniel (5 products with blank fields)
      final produtosDaniel = <ProdutoModel>[
        ProdutoModel(
          codigoBarras: '7891203010056',
          nome: 'Pão de Forma',
          fabricante: 'Panco',
          idColaborador: idDaniel,
        ),
        ProdutoModel(
          codigoBarras: '7896025801172',
          nome: 'Ketchup',
          fabricante: 'Cepera',
          idColaborador: idDaniel,
          fotoBase64: ''

        ),
        ProdutoModel(
          codigoBarras: '7622300990701',
          nome: 'Biscoito Salgado',
          fabricante: 'Club Social',
          idColaborador: idDaniel,
          fotoBase64: ''
        ),
      ];

      // Create products for Vinicius (5 products with blank fields)
      final produtosVinicius = <ProdutoModel>[
        ProdutoModel(
          codigoBarras: '7898215157403',
          nome: 'Leite Integral',
          fabricante: 'Ninho',
          idColaborador: idVinicius,
          fotoBase64: ''
        ),
        ProdutoModel(
          codigoBarras: '7891203069719',
          nome: 'Bisnaguinhas',
          fabricante: 'Panco',
          idColaborador: idVinicius,
        ),
      ];

      final produtosRicardo = <ProdutoModel>[
        ProdutoModel(
          codigoBarras: '7892999150100',
          nome: 'Leite UHT Desnatado',
          fabricante: 'Leco',
          idColaborador: idRicardo,
          fotoBase64: ''
        ),
        ProdutoModel(
          codigoBarras: '7897972001103',
          nome: 'Bisnaguinhas',
          fabricante: 'Kim',
          idColaborador: idRicardo,
        ),
        ProdutoModel(
          codigoBarras: '7896005404218',
          nome: 'Suco de Uva',
          fabricante: 'Maguary',
          idColaborador: idRicardo,
          fotoBase64: ''
        ),
      ];

      // Manual mapping: define which product barcodes should be linked to each store name
      // for each collaborator. Edit these maps to control seed linking exactly.
      final manualLojaProdutosDaniel = <String, List<String>>{
        'Mercado Central SP': ['7891203010056', '7896025801172', '7622300990701'],
        'Super Vale SP': ['7896025801172', '7622300990701'],
        'Atacado São Paulo': ['7622300990701'],
      };

      final manualLojaProdutosVinicius = <String, List<String>>{
        'Mercado Norte SP': ['7898215157403', '7891203069719'],
        'Super Sul SP': ['7891203069719'],
        'Atacado Central': ['7898215157403', '7891203069719'],
      };

      final manualLojaProdutosRicardo = <String, List<String>>{
        'Mercado Sul SP': ['7892999150100', '7897972001103', '7896005404218'],
        'Super Norte SP': ['7892999150100'],
        'Atacado do Vale': ['7892999150100', '7897972001103'],
      };

      // Insert products
      await dataSource.upsertProdutos(produtosDaniel);
      await dataSource.upsertProdutos(produtosVinicius);
      await dataSource.upsertProdutos(produtosRicardo);

      // Build loja_produto lists from manual mappings and upsert in batch.
      // This mirrors the pattern used for `lojasDaniel` / `upsertLojas`.
      final listaLojaProdutoDaniel = <LojaProdutoModel>[];
      final lojasDanielPersist = await dataSource.listarLojasPorColaborador(idDaniel);
      for (final loja in lojasDanielPersist) {
        final barcodes = manualLojaProdutosDaniel[loja.nome];
        if (barcodes == null) continue;
        for (final barcode in barcodes) {
          final persisted = await dataSource.buscarProdutoPorCodigoBarrasColaborador(barcode, idDaniel);
          if (persisted != null && persisted.id != null && loja.id != null) {
            listaLojaProdutoDaniel.add(LojaProdutoModel(
              lojaId: loja.id,
              produtoId: persisted.id,
              colaboradorId: idDaniel,
            ));
          }
        }
      }

      final listaLojaProdutoVinicius = <LojaProdutoModel>[];
      final lojasViniciusPersist = await dataSource.listarLojasPorColaborador(idVinicius);
      for (final loja in lojasViniciusPersist) {
        final barcodes = manualLojaProdutosVinicius[loja.nome];
        if (barcodes == null) continue;
        for (final barcode in barcodes) {
          final persisted = await dataSource.buscarProdutoPorCodigoBarrasColaborador(barcode, idVinicius);
          if (persisted != null && persisted.id != null && loja.id != null) {
            listaLojaProdutoVinicius.add(LojaProdutoModel(
              lojaId: loja.id,
              produtoId: persisted.id,
              colaboradorId: idVinicius,
            ));
          }
        }
      }

      final listaLojaProdutoRicardo = <LojaProdutoModel>[];
      final lojasRicardoPersist = await dataSource.listarLojasPorColaborador(idRicardo);
      for (final loja in lojasRicardoPersist) {
        final barcodes = manualLojaProdutosRicardo[loja.nome];
        if (barcodes == null) continue;
        for (final barcode in barcodes) {
          final persisted = await dataSource.buscarProdutoPorCodigoBarrasColaborador(barcode, idRicardo);
          if (persisted != null && persisted.id != null && loja.id != null) {
            listaLojaProdutoRicardo.add(LojaProdutoModel(
              lojaId: loja.id,
              produtoId: persisted.id,
              colaboradorId: idRicardo,
            ));
          }
        }
      }

      if (listaLojaProdutoDaniel.isNotEmpty) {
        await dataSource.upsertLojaProdutos(listaLojaProdutoDaniel);
      }
      if (listaLojaProdutoVinicius.isNotEmpty) {
        await dataSource.upsertLojaProdutos(listaLojaProdutoVinicius);
      }
      if (listaLojaProdutoRicardo.isNotEmpty) {
        await dataSource.upsertLojaProdutos(listaLojaProdutoRicardo);
      }
    } catch (e) {
      // Silently ignore errors (seed data already exists)
    }
  }
}
